from render_paths import *
from scipy.ndimage import distance_transform_edt
import json,time
T=np.array(Image.open('/app/target.png'))[:,:,0]<100
# Coordinate refinement of eight lengthwise variable-width brush paths.
# No fill trajectories are introduced.
orig=[np.array(p,float) for p in paths]
ps=[p.copy() for p in orig]
def raster(p):
 im=Image.new('1',(1024,1024));d=ImageDraw.Draw(im)
 for x,y,w in interp_path(p,step=1.8):
  d.ellipse((x-w/2,y-w/2,x+w/2,y+w/2),fill=1)
 return np.array(im)
ms=[raster(p) for p in ps]
far=(distance_transform_edt(~T)>4.5)
def loss(m,p,base):
 # Penalize ink outside target somewhat more than missed edge pixels.
 return np.sum(T&~m)+1.25*np.sum(m&~T)+2*np.sum(m&far)+.7*np.sum((p-base)**2)
for step in [3,2,1,.5]:
 for repeat in range(2):
  changes=0
  for i,p in enumerate(ps):
   other=np.logical_or.reduce([m for j,m in enumerate(ms) if j!=i]); best=loss(ms[i]|other,p,orig[i])
   for j in range(len(p)):
    for k in range(3):
     val=p[j,k]; winner=None
     for direction in [-1,1]:
      p[j,k]=val+step*direction
      if abs(p[j,k]-orig[i][j,k])>12 or (k==2 and p[j,k]<2):continue
      m=raster(p);l=loss(m|other,p,orig[i])
      if l<best:best=l;winner=(p[j,k],m)
     p[j,k]=val
     if winner is not None:p[j,k]=winner[0];ms[i]=winner[1];changes+=1
  u=np.logical_or.reduce(ms)
  print(step,repeat,changes,'iou',np.sum(u&T)/np.sum(u|T),flush=True)
json.dump([p.tolist() for p in ps],open('/app/output/optimized_paths.json','w'))
rgb=np.full((1024,1024,3),245,np.uint8);rgb[T]=30;rgb[u&~T]=[240,60,60];rgb[T&~u]=[50,130,240]
Image.fromarray(rgb).save('/app/output/optimized.png')
